  "implementation": "def solve(case):
    nodes = case['nodes']
    core_distances = case['core_distance']
    distances = case['distances']

    # Build mutual reachability edges
    edges = []
    for u, v, d in distances:
        m = max(core_distances[u], core_distances[v], d)
        # Canonicalize endpoint order (lexicographic)
        if u <= v:
            a, b = u, v
        else:
            a, b = v, u
        edges.append((a, b, m))

    # Sort deterministically: weight, then first endpoint, then second endpoint
    edges.sort(key=lambda e: (e[2], e[0], e[1]))

    # Union-Find structure
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    n = len(nodes)
    mst_edges = []
    total_weight = 0.0

    for u, v, w in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError("Graph is disconnected, cannot form MST")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }"
}
